import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"早期启动","description":"","frontmatter":{"title":"早期启动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/early-boot.md","filePath":"cs/early-boot.md","lastUpdated":1789023840000}'),m={name:"cs/early-boot.md"};function h(_,a,f,u,B,E){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="早期启动" tabindex="-1">早期启动 <a class="header-anchor" href="#早期启动" aria-label="Permalink to &quot;早期启动&quot;">​</a></h1><div class="epigraph"><p>复位后引导程序把内核装入内存并跳转；内核解压、建页表、初始化中断与分配器，直到能够挂上根并创建 pid 1。</p><footer>—— 据 Tanenbaum MOS；Love；Bovet 对 Linux 启动链的整理</footer></div><p><a href="/cs/sysfs-proc">上一课</a>假定内核已在跑。<a href="/cs/kernel-user">内核与用户态</a> 说复位先进入内核。<a href="/cs/buddy-allocator">buddy</a> 与中断向量都需要有人第一次建好。缺口是<strong>早期启动链</strong>：固件/引导加载器 → 内核入口 → 解压 → <code>start_kernel</code> 量级的初始化顺序。不把每家 SoC 的 bootrom 写成手册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPU 复位时没有页表、没有驱动、没有 FS。引导加载器在实模式或固件环境读磁盘/网络，把内核映像放到约定物理地址，传递命令行与内存图。内核必须：开分页（<a href="/cs/paging-vm">分页</a> 的第一套表）、识别内存、初始化 buddy、中断控制器、调度器、VFS 根。缺口是这条因果顺序，而不是某个启动徽标。</p><p><span class="marginnote">initramfs 是内存里的早期根，用于加载根设备模块再切到真根。设备树或 ACPI 描述板级硬件。本课合并这些，不当三篇。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固件 → bootloader（如 GRUB、UEFI）→ 跳内核入口。入口：关干扰、建临时映射、解压缩。<code>start_kernel</code>：内存、调度、时间（jiffies 来源）、驱动子系统、挂载 initramfs、启动 pid 1 前的 rest_init。失败通常 panic，因为还没有用户空间可报错。命令行可指定 <code>root=</code>。</p>',8)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RST%5B%22%E5%A4%8D%E4%BD%8D%2F%E5%9B%BA%E4%BB%B6%22%5D%20--%3E%20BL%5B%22%E5%BC%95%E5%AF%BC%E5%8A%A0%E8%BD%BD%E5%99%A8%22%5D%0A%20%20BL%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E5%85%A5%E5%8F%A3%E4%B8%8E%E8%A7%A3%E5%8E%8B%22%5D%0A%20%20K%20--%3E%20SK%5B%22start_kernel%22%5D%0A%20%20SK%20--%3E%20RAMFS%5B%22initramfs%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>早期启动把组成课的「上电」接到 OS 对象的第一次出现：没有 buddy 就没有后续缺页；没有中断就没有 DMA 完成。用户/内核分裂的第一套内核映射在这里建立。不要把安全启动密钥管理写成攻击或绕过指南；只承认引导路径可被验签。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 kexec 的全部协议。不保证嵌入式无 bootloader（有的直接进内核）。下一课：内核把 CPU 交给用户空间的 pid 1，由它挂真根、拉服务。</p><p>后课默认：内核已能调度并有早期根。用户空间的第一个进程，下一课 init。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引导加载器装核；内核建页表与分配器后才能挂根。</li><li>initramfs 解决「根设备驱动还不在根上」的环。</li><li>pid 1 与真根是 init 课的缺口。</li><li>出处：Tanenbaum <em>MOS</em>；Love, <em>LKD</em>；Bovet and Cesati, <em>ULK</em>。</li></ul>',7))])}const S=i(m,[["render",h]]);export{A as __pageData,S as default};
